WITH kept_keys AS (SELECT status, store_id FROM orders INTERSECT SELECT status, store_id FROM orders WHERE store_id IN (7, 25)), kept_rows AS (SELECT s.* FROM orders s INNER JOIN kept_keys k ON s.status = k.status AND s.store_id = k.store_id) SELECT DATE_TRUNC('MONTH', order_date) AS activity_month, DATE_TRUNC('YEAR', order_date) AS year_start, DATE_TRUNC('WEEK', order_date) AS week_start, ROUND(AVG(discount), 2) AS avg_discount, APPROX_PERCENTILE(amount, 0.5) AS amount_p50, AVG(discount) AS avg_discount_2, STDDEV_SAMP(amount) AS amount_stddev, AVG(shipping_fee) FILTER (WHERE status = 'RETURNED') AS returned_avg_shipping_fee, COUNT_IF(status = 'RETURNED') AS returned_events FROM kept_rows GROUP BY 1, 2, 3
